-- V3__inventory.sql — stock reservation ledger for checkout safety.
-- Mirrors V1/V2 conventions: GENERATED BY DEFAULT AS IDENTITY (lets JPA re-set IDs
-- in tests), TIMESTAMPTZ, and application-enforced status enums.

CREATE TABLE stock_reservations (
    id            BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id      BIGINT       REFERENCES orders (id) ON DELETE CASCADE,
    product_id    BIGINT       NOT NULL REFERENCES products (id) ON DELETE CASCADE,
    variant_id    BIGINT       REFERENCES product_variants (id) ON DELETE CASCADE,
    user_id       BIGINT       REFERENCES users (id) ON DELETE SET NULL,
    quantity      INTEGER      NOT NULL,
    status        VARCHAR(20)  NOT NULL DEFAULT 'ACTIVE',
    expires_at    TIMESTAMPTZ,
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version       BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT chk_stock_reservations_quantity CHECK (quantity > 0),
    CONSTRAINT chk_stock_reservations_status CHECK (
        status IN ('ACTIVE', 'COMMITTED', 'RELEASED'))
);

CREATE INDEX idx_stock_reservations_order ON stock_reservations (order_id);
CREATE INDEX idx_stock_reservations_product ON stock_reservations (product_id);
CREATE INDEX idx_stock_reservations_user ON stock_reservations (user_id);
CREATE INDEX idx_stock_reservations_status ON stock_reservations (status);
CREATE INDEX idx_stock_reservations_expires_at ON stock_reservations (expires_at);

-- ── LOW STOCK ALERTS ─────────────────────────────────────────────────────────
-- Raised by the inventory service when available stock drops to/below a threshold.
-- acknowledged_at NULL = still open for admin review; the service raises a new alert
-- only when no open one exists for the same product/variant (no alert spam).
CREATE TABLE low_stock_alerts (
    id              BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_id      BIGINT       NOT NULL REFERENCES products (id) ON DELETE CASCADE,
    variant_id      BIGINT       REFERENCES product_variants (id) ON DELETE CASCADE,
    threshold       INTEGER      NOT NULL,
    current_stock   INTEGER      NOT NULL,
    acknowledged_at TIMESTAMPTZ,
    notified_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version         BIGINT       NOT NULL DEFAULT 0,

    CONSTRAINT chk_low_stock_alerts_threshold CHECK (threshold >= 0)
);
CREATE INDEX idx_low_stock_alerts_product ON low_stock_alerts (product_id);
CREATE INDEX idx_low_stock_alerts_open    ON low_stock_alerts (acknowledged_at);
